'use strict';
// Present selection and lexicon maintenance consistently; retain the original save/import contracts.
const wcBase={configPanel,modalContent,handleAction,closeModal};
const WC_KIND={
 stop:{name:'停用词',title:'不参与统计的词',hint:'过滤无关词语，让词云更聚焦。',example:'例如：“以及”“有关”不计入词频。',empty:'词库中还没有停用词。'},
 user:{name:'用户新词',title:'按完整词语识别的词',hint:'将专有名称、业务术语作为一个词识别。',example:'例如：“专项资金”整体识别，不拆开。',empty:'词库中还没有用户新词。'}
};
let wcLexReturn=null;
TW_META.word=['添加分析资料','设置统计规则','添加资料后，可设置停用词、完整词语和展示词数，再开始分析。'];
function wcKinds(p){p.kind=p.kind==='user'?'user':'stop';p.query??='';p.page??=1;p.size??=20;return p;}
function wcTabs(kind,counts){return '<nav class="wc-kind-tabs" aria-label="词语类型">'+Object.entries(WC_KIND).map(([key,meta])=>'<button type="button" data-action="wc-kind" data-kind="'+key+'" aria-pressed="'+(key===kind)+'" class="'+(key===kind?'active':'')+'">'+meta.name+' <strong>'+counts[key]+'</strong></button>').join('')+'</nav>';}
function wcExplanation(kind){const meta=WC_KIND[kind];return '<div class="wc-explanation"><strong>'+meta.title+'</strong><p>'+meta.hint+'<span>'+meta.example+'</span></p></div>';}
function wcPager(p,count){const pages=Math.max(1,Math.ceil(count/p.size));p.page=Math.max(1,Math.min(p.page,pages));return '<div class="wc-pagination"><span>共 <strong>'+count+'</strong> 条</span><div>'+B('上一页','wc-page','sm','data-step="-1" '+(p.page===1?'disabled':''))+'<span>第 '+p.page+' / '+pages+' 页</span>'+B('下一页','wc-page','sm','data-step="1" '+(p.page===pages?'disabled':''))+'</div></div>';}
function wcCard(kind,words,locked){const m=WC_KIND[kind];return '<section class="wc-rule-card"><div class="wc-rule-title"><h3>'+m.name+'</h3><span>已'+(kind==='stop'?'排除':'启用')+' <strong>'+words.length+'</strong> 个</span></div><p>'+m.hint+'</p><p class="wc-rule-example">'+m.example+'</p><div class="wc-word-preview">'+(words.length?words.slice(0,4).map(w=>'<span>'+E(w)+'</span>').join('')+(words.length>4?'<span>等 '+words.length+' 个</span>':''):'<span class="wc-empty-preview">'+(kind==='stop'?'未设置排除词':'未设置完整词语')+'</span>')+'</div>'+B(I(kind==='stop'?'filter':'book','icon-sm')+(locked?'查看本次'+m.name:'设置'+m.name),'wc-select','sm w100','data-kind="'+kind+'"')+'</section>';}
configPanel=function(){const html=wcBase.configPanel();if(state.toolId!=='word')return html;const root=document.createElement('div');root.innerHTML=html;const panel=root.querySelector('aside');if(!panel)return html;panel.classList.add('wc-config');const task=currentTask(),c=awConfig(),locked=!!task,stop=task?.stopwords||c.lexiconSelection.stop||state.stopwords,user=task?.newwords||c.lexiconSelection.user||state.newwords;const heading=panel.querySelector('.ew-panel-head h2');if(heading)heading.innerHTML=(locked?'':'<span class="tw-step">Step 3</span>')+'设置统计规则';panel.setAttribute('aria-label',locked?'本次统计规则':'Step 3 设置统计规则');panel.querySelector('.ew-config-body').innerHTML='<div class="wc-intro"><span>'+(locked?'本次分析采用的规则，只读查看。':'按需要调整以下统计规则。')+'</span>'+(!locked?B(I('edit','icon-sm')+'维护词库','lexicon','ghost sm'):'')+'</div>'+wcCard('stop',stop,locked)+wcCard('user',user,locked)+'<section class="wc-top"><label for="aw-top">展示高频词数量</label><div class="wc-top-input"><input id="aw-top" aria-label="展示词数" type="number" min="10" max="500" data-wc-config="top" value="'+E(c.top)+'" '+(locked?'disabled':'')+'><span>个</span></div>'+(!locked?'<div class="wc-top-presets" aria-label="常用展示词数">'+[30,50,100].map(n=>'<button type="button" data-action="wc-top" data-value="'+n+'" aria-pressed="'+(+c.top===n)+'">'+n+' 个</button>').join('')+'</div>':'')+'<p>按出现次数取前 10–500 个词展示。</p><p id="wc-top-error" class="error" role="alert"></p></section>'+'<p class="wc-note">词频表示出现次数，不代表风险程度。</p>';return root.innerHTML;};
function wcAvailableWords(kind){const task=currentTask();if(task)return kind==='stop'?task.stopwords||[]:task.newwords||[];return [...new Set([...(kind==='stop'?state.stopwords:state.newwords),...(ws('word').config.lexiconSelection?.[kind]||[])])];}
function wcSelectionRows(p){return wcAvailableWords(p.kind).filter(w=>w.toLowerCase().includes(p.query.toLowerCase()));}
wordSelectionModal=function(){const p=wcKinds(modalData),task=currentTask(),locked=!!task,kind=p.kind,rows=wcSelectionRows(p),pages=Math.max(1,Math.ceil(rows.length/p.size));p.page=Math.max(1,Math.min(p.page,pages));const shown=pageItems(rows,p.page,p.size),selected=editorDraft[kind],pageAll=shown.length&&shown.every(w=>selected.includes(w)),counts={stop:wcAvailableWords('stop').length,user:wcAvailableWords('user').length};return modalFrame(locked?'本次分析用词':'选择本次分析用词',locked?'查看执行时使用的词表，后续词库调整不会改变本次记录。':'勾选需要使用的词语，确认后用于本次统计。',wcTabs(kind,counts)+wcExplanation(kind)+'<div class="wc-choice-toolbar"><div class="search">'+I('search','icon-sm')+'<input id="wc-query" data-wc-input="query" aria-label="搜索本次可选词条" placeholder="查找'+WC_KIND[kind].name+'" value="'+E(p.query)+'"></div><span>本类已选 <strong>'+selected.length+'</strong> 个</span></div>'+(!locked?'<div class="wc-selection-actions">'+B('选择全部页（'+rows.length+'）','wc-all','ghost sm',rows.length?'':'disabled')+B('清空本类选择','v2-word-none','ghost sm','data-kind="'+kind+'" '+(!selected.length?'disabled':''))+'</div>':'')+'<div class="wc-table-scroll"><table class="table wc-choice-table"><thead><tr>'+(!locked?'<th><label><input type="checkbox" data-wc-change="page" aria-label="选择本页词条" '+(pageAll?'checked':'')+' '+(!shown.length?'disabled':'')+'>本页</label></th>':'')+'<th>词语</th></tr></thead><tbody>'+shown.map(w=>'<tr>'+(!locked?'<td><input type="checkbox" data-wc-change="word" value="'+E(w)+'" aria-label="选择 '+E(w)+'" '+(selected.includes(w)?'checked':'')+'></td>':'')+'<td>'+E(w)+'</td></tr>').join('')+'</tbody></table>'+(!rows.length?'<div class="wc-empty">'+(p.query?'没有匹配的词语。':WC_KIND[kind].empty)+(locked?'':'<p>可到“维护词库”添加或导入。</p>')+'</div>':'')+'</div>'+wcPager(p,rows.length),(!locked?'<div class="wc-selection-footer"><span>本次：停用词 <strong>'+editorDraft.stop.length+'</strong> 个 · 新词 <strong>'+editorDraft.user.length+'</strong> 个</span>'+B('维护词库','wc-manage','ghost sm')+'</div>':'')+'<div class="row">'+B(locked?'关闭':'取消','close-modal')+(locked?'':B('应用本次选择','v2-save-editor','primary'))+'</div>','wc-dialog wc-selection-dialog');};
awLexOpen=function(){const data={stop:[...state.stopwords],user:[...state.newwords]};openModal('aw-lexicon',{data,initial:JSON.stringify(data),query:'',kind:'stop',page:1,size:20});};
awLexModal=function(p){wcKinds(p);const rows=awLexRows(p),pages=Math.max(1,Math.ceil(rows.length/p.size));p.page=Math.max(1,Math.min(p.page,pages));return modalFrame('维护词库','维护可供后续分析选择的词条。保存词库后，仍可分别调整本次勾选。',wcTabs(p.kind,{stop:p.data.stop.length,user:p.data.user.length})+wcExplanation(p.kind)+'<div class="wc-maintain-toolbar"><div class="search">'+I('search','icon-sm')+'<input id="aw-lex-query" aria-label="搜索词库" data-aw-input="lex" placeholder="查找'+WC_KIND[p.kind].name+'" value="'+E(p.query)+'"></div>'+B(I('plus','icon-sm')+'添加词条','aw-lex-add','primary sm','data-kind="'+p.kind+'"')+B(I('upload','icon-sm')+'导入词表','aw-lex-import','sm','data-kind="'+p.kind+'"')+B(I('download','icon-sm')+'导出词库','aw-lex-export','ghost sm')+'</div><div class="aw-editor-scroll wc-table-scroll"><table class="table aw-lex-table"><thead><tr><th>序号</th><th>词语</th><th>操作</th></tr></thead><tbody>'+pageItems(rows,p.page,p.size).map((r,i)=>'<tr><td>'+((p.page-1)*p.size+i+1)+'</td><td>'+E(r.word)+'</td><td><div class="row">'+A('编辑','aw-lex-edit','data-kind="'+r.kind+'" data-index="'+r.index+'"')+A('删除','aw-lex-delete','data-kind="'+r.kind+'" data-index="'+r.index+'"')+'</div></td></tr>').join('')+'</tbody></table>'+(!rows.length?'<div class="wc-empty">'+(p.query?'没有匹配的词语。':WC_KIND[p.kind].empty)+'<p>点击“添加词条”，或导入已有词表。</p></div>':'')+'</div>'+wcPager(p,rows.length)+'<p class="error" id="aw-lex-error" role="alert"></p>',B('取消','close-modal')+B('保存词库','aw-lex-save','primary'),'wc-dialog aw-lex-dialog');};
modalContent=function(){let html=wcBase.modalContent();if(!['aw-lex-word','aw-lex-import','aw-lex-review'].includes(modal))return html;const root=document.createElement('div');root.innerHTML=html;root.querySelector('.modal')?.classList.add('wc-child-dialog');if(modal==='aw-lex-word'){const title=root.querySelector('.modalhead h2');if(title)title.textContent=(modalData.edit?'编辑':'添加')+WC_KIND[modalData.kind].name;root.querySelector('.modalbody')?.insertAdjacentHTML('afterbegin','<p class="wc-edit-help" id="wc-edit-help">'+WC_KIND[modalData.kind].hint+' '+WC_KIND[modalData.kind].example+'</p>');const save=root.querySelector('[data-action=aw-lex-word-save]');if(save)save.textContent='确认词条';}if(modal==='aw-lex-import'){root.querySelector('.modalbody')?.insertAdjacentHTML('afterbegin','<p class="wc-edit-help">导入到'+WC_KIND[modalData.kind].name+'。每行一个词，先检查重复和类型冲突，再确认加入词库清单。</p>');const subtitle=root.querySelector('.modalhead p');if(subtitle)subtitle.textContent='选择词表文件，或粘贴需要导入的词条。';const fileInput=root.querySelector('#aw-lex-file');if(fileInput){fileInput.hidden=true;fileInput.insertAdjacentHTML('beforebegin','<button type="button" data-action="wc-pick-file" class="wc-file-picker" aria-controls="aw-lex-file">'+I('upload','icon-sm')+'选择 TXT / JSON 文件</button><span id="wc-file-name" class="wc-file-name">尚未选择文件</span>');}const text=root.querySelector('#aw-lex-text');if(text)text.placeholder='例如：\n'+(modalData.kind==='stop'?'以及\n有关\n相关':'专项资金\n园区建设中心');}return root.innerHTML;};
function wcRestoreSelection(){const back=wcLexReturn;wcLexReturn=null;if(!back)return;editorDraft=back.draft;if(!ws('word').reanalysisSource)for(const kind of ['stop','user'])editorDraft[kind]=editorDraft[kind].filter(w=>(kind==='stop'?state.stopwords:state.newwords).includes(w));openModal('v2-word-selection',back.data);}
handleAction=function(action,el){
 if(action==='wc-pick-file'){document.getElementById('aw-lex-file')?.click();return;}
 if(action==='wc-select'){const out=wcBase.handleAction('v2-word-selection',el);modalData.kind=el.dataset.kind||'stop';modalData.page=1;paintModal();return out;}
 if(action==='wc-kind'){modalData.kind=el.dataset.kind;modalData.query='';modalData.page=1;paintModal();return;}
 if(action==='wc-page'){modalData.page+=+el.dataset.step;paintModal();return;}
 if(action==='wc-all'&&modal==='v2-word-selection'&&!currentTask()){editorDraft[modalData.kind]=[...new Set([...editorDraft[modalData.kind],...wcSelectionRows(modalData)])];paintModal();return;}
 if(action==='wc-top'&&!currentTask()){document.activeElement?.blur();ws('word').config.top=+el.dataset.value;persist();render();return;}
 if(action==='wc-manage'){wcLexReturn={draft:structuredClone(editorDraft),data:structuredClone(modalData)};const kind=modalData.kind;awLexOpen();modalData.kind=kind;paintModal();return;}
 if(action==='aw-lex-save'&&wcLexReturn){wcBase.handleAction(action,el);if(!modal)wcRestoreSelection();return;}
 if(action==='aw-discard'&&modalData.type==='aw-lexicon'&&wcLexReturn){wcRestoreSelection();return;}
 return wcBase.handleAction(action,el);
};
closeModal=function(){if(modal==='aw-lexicon'&&wcLexReturn&&!awDirty(modal,modalData)){wcRestoreSelection();return;}return wcBase.closeModal();};
function wcTopInput(el){if(currentTask())return;const n=el.value===''?'':Number(el.value),valid=Number.isInteger(n)&&n>=10&&n<=500;ws('word').config.top=n;el.setAttribute('aria-invalid',String(!valid));const error=document.getElementById('wc-top-error');if(error)error.textContent=valid?'':'请输入 10–500 之间的整数。';document.querySelectorAll('.wc-top-presets button').forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.value===n)));return valid;}
window.addEventListener('input',e=>{const el=e.target;if(el.dataset.wcConfig==='top'){wcTopInput(el);return;}if(el.dataset.wcInput!=='query')return;modalData.query=el.value;modalData.page=1;const pos=el.selectionStart;paintModal();const next=document.getElementById('wc-query');next?.focus();next?.setSelectionRange(pos,pos);},true);
window.addEventListener('change',e=>{const el=e.target;if(el.dataset.wcConfig==='top'){e.stopImmediatePropagation();if(wcTopInput(el))persist();return;}if(el.id==='aw-lex-file'){const name=document.getElementById('wc-file-name');if(name)name.textContent=el.files?.[0]?.name||'尚未选择文件';return;}if(el.id==='aw-word-kind'){const help=document.getElementById('wc-edit-help');if(help)help.textContent=WC_KIND[el.value].hint+' '+WC_KIND[el.value].example;return;}if(!el.dataset.wcChange||modal!=='v2-word-selection'||currentTask())return;e.stopImmediatePropagation();const kind=modalData.kind,words=el.dataset.wcChange==='page'?pageItems(wcSelectionRows(modalData),modalData.page,modalData.size):[el.value];editorDraft[kind]=el.checked?[...new Set([...editorDraft[kind],...words])]:editorDraft[kind].filter(w=>!words.includes(w));paintModal();},true);
render();
